draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1668', W/2, H/2 + 70);
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 70, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 - 10);
  ctx.lineTo(W/2 - 70, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2 - 10);
  ctx.lineTo(W/2 + 70, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
